using System;using System.Drawing;using System.IO;using System.Collections.Generic;
namespace WinterDesk {internal static class RevisionChecks {
 static void Check(bool b,string why){if(!b)throw new Exception(why);}
 static void Main(){Directory.CreateDirectory("work/checks23");
 StackOnWindow();SquirrelRoutes();SnowCaps();CadenceFamilyAndSnow();
 var gesture=new ThrowGesture();gesture.Begin(0,0,0);for(int n=1;n<=10;n++)gesture.Move(n*15,100-n*10,n*.01,1);double vx,vy;gesture.Release(.101,out vx,out vy);Check(vx>900&&vy< -600,"throw follows mouse speed direction");gesture.Release(1,out vx,out vy);Check(Math.Abs(vx)<1&&Math.Abs(vy)<1,"holding still cancels throw");
 var one=new List<Ledge>{new Ledge{Handle=new IntPtr(1),Bounds=new Rectangle(300,200,400,400)}};foreach(var points in new[]{new double[]{0,300,900,300,-1,0},new double[]{900,300,0,300,1,0},new double[]{400,0,400,900,0,-1},new double[]{400,900,400,0,0,1}}){var hit=SnowThrowPhysics.Sweep(points[0],points[1],points[2],points[3],20,one);Check(hit.Hit&&hit.NX==points[4]&&hit.NY==points[5],"swept fast collision with correct normal");}Check(!SnowThrowPhysics.Sweep(0,100,900,100,20,one).Hit,"near miss");Check(!SnowThrowPhysics.Sweep(400,300,900,300,20,one).Hit,"ball initially over window may exit");one[0].Blockers.Add(new Rectangle(200,200,200,400));Check(!SnowThrowPhysics.Sweep(0,300,900,300,20,one).Hit,"occluded edge ignored");Console.WriteLine("PASS: gesture momentum, stationary release, fast collisions on four sides, near miss and blockers.");
 for(int i=0;i<100;i++){double time=i*.07;int f=WorkerCycle.Frame(time,60,1);Check(f>=0&&f<256,"worker frame");Check(WorkerCycle.Moving(time)?f<128:f>=128,"walk versus scoop throw");}Check(!WorkerCycle.Moving(3.2),"throw pauses travel");double cycles=110/(180.0);Check(cycles<1,"run sheet less than once a second");Console.WriteLine("PASS: walk/throw phases with paused travel; moderate distance-based penguin cadence.");
 var snow=new SnowmanMotion(400,100,1,false,1);for(int i=0;i<2000&&snow.State==SnowmanState.Falling;i++)snow.Tick(1.0/120,900,0,1400);Check(snow.State==SnowmanState.Landing,"snowman lands");var poses=new HashSet<int>();for(int i=0;i<140;i++){poses.Add(snow.Pose);snow.Tick(1.0/120,900,0,1400);}Check(poses.Count>=14&&snow.State!=SnowmanState.Landing&&snow.State!=SnowmanState.Awakening,"seated impact and rise animate continuously");var peng=new PetMotion(400,100,1){State=PetState.Falling};for(int i=0;i<2000&&peng.State==PetState.Falling;i++)peng.Tick(1.0/120,new List<Ledge>(),x=>900);Check(peng.State==PetState.Landing,"penguin lands");for(int i=0;i<195;i++)peng.Tick(1.0/120,new List<Ledge>(),x=>900);Check(peng.State==PetState.Running,"penguin recovers then runs");Console.WriteLine("PASS: seated landings progress through recovery and return to motion.");
 Contact();Cache();Soak();Preview();FramePreparation.Stop();DrawnArt.Release();}
 static void SquirrelRoutes(){var area=new Rectangle(0,0,1600,1100);foreach(int top in new[]{180,400})foreach(int height in new[]{160,550})foreach(int side in new[]{-1,1})for(int seed=0;seed<4;seed++){var roof=new Ledge{Handle=new IntPtr(7),Bounds=new Rectangle(450,top,650,height)};var routes=SquirrelRouteBuilder.Build(new List<Ledge>{roof},area,1000,.65f);Check(routes.Count==2,"no imaginary climbing supports");var m=new SquirrelMotion(routes[1],0,.65f,seed,0,1600,0,side);bool wall=false,climbed=false,mounted=false;int wallJumps=0,lastFrame=-1;var climbFrames=new HashSet<int>();for(int n=0;n<11000&&m.State!=SquirrelState.Done;n++){var oldState=m.State;m.Tick(1.0/120,routes,0,1600);if(m.Frame>=128)Check(m.Frame<144,"new frame bounds");if(m.State==SquirrelState.Climbing){Check(m.Age<2.3,"climb completes within 2.3 seconds");if(oldState!=m.State){wallJumps++;wall=true;}Check(Math.Abs(m.X-(m.EdgeSide<0?roof.Bounds.Left+1:roof.Bounds.Right-1))<.01,"paws locked to real vertical edge");Check(m.Y>=roof.Bounds.Top-.1&&m.Y<=roof.Bounds.Bottom,"climb catch within real window");climbFrames.Add(m.Frame);if(!climbed&&m.Age>.2){roof.Bounds.Offset(12,8);climbed=true;}}if(m.State==SquirrelState.Mounting){Check(m.ClimbDistance/Math.Max(1,m.ClimbStride)<=3.01,"at most three climb cycles");mounted=true;}if(m.State==SquirrelState.Landing&&m.Support==roof.Handle){Check(m.Age<.02&&wall&&mounted,"one jump then climb then mount before roof landing");lastFrame=n;break;}}Check(lastFrame>=0&&wallJumps==1&&climbFrames.Count>=4,"high window reached by one catch jump and animated crawl");m.Grab(m.X,m.Y);m.Drag(1300,200);m.Drop();for(int n=0;n<1000&&m.State==SquirrelState.Falling;n++)m.Tick(1.0/120,routes,0,1600);Check(m.State==SquirrelState.Landing,"drag and release still land on actual support");}
 var window=new Ledge{Handle=new IntPtr(3),Bounds=new Rectangle(350,200,600,500)};var ground=new Ledge{Handle=new IntPtr(-2),Bounds=new Rectangle(-1000,1000,4000,1)};var route=new List<Ledge>{window,ground};var missing=new SquirrelMotion(ground,0,.65f,4,0,1600);for(int i=0;i<5000&&missing.State!=SquirrelState.Climbing;i++)missing.Tick(1.0/120,route,0,1600);Check(missing.State==SquirrelState.Climbing,"setup window climb");route.RemoveAt(0);missing.Tick(1.0/120,route,0,1600);Check(missing.State==SquirrelState.Falling,"closing climbed window causes fall, not invisible support");Console.WriteLine("PASS: 32 routes, no air footholds, one large catch jump, real-frame crawl, mantle, moving/closed windows and drag release.");}
 static void SnowCaps(){using(var m=new SnowModel(640,1,15)){for(int i=0;i<m.Depth.Length;i++)m.Depth[i]=35+5*(float)Math.Sin(i*.07);double mass=m.Mass;using(var window=m.Render(true))using(var desktop=m.Render()){int pad=SnowMaterial.Padding(m);Check(window.Width==m.Width+2*pad&&window.Height>m.Height,"cap has outside/below room");bool left=false,right=false,below=false;for(int y=0;y<window.Height;y++){Check(window.GetPixel(0,y).A==0&&window.GetPixel(window.Width-1,y).A==0,"rounded caps fit canvas without cuts");for(int x=0;x<window.Width;x++){if(window.GetPixel(x,y).A<80)continue;if(x<pad)left=true;if(x>pad+m.Width)right=true;if(y>m.Height+2)below=true;}}Check(left&&right&&below,"both rounded overhanging ends rendered");Check(desktop.Width==m.Width&&desktop.Height==m.Height,"desktop bank dimensions retained");Check(Math.Abs(m.Mass-mass)<.001,"decorative edge shape leaves snow mass unchanged");using(var image=Artwork.Canvas(860,300))using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(35,48,64));g.FillRectangle(Brushes.SlateGray,90,140,640,160);g.DrawImageUnscaled(window,90-pad,140-m.Height);window.Save("work/checks23/cap-alpha.png");image.Save("work/checks23/cap-preview.png");}}}Console.WriteLine("PASS: natural cap ends, hanging edge clearance, unchanged desktop and mass.");}
 static void CadenceFamilyAndSnow(){var squirrel=new WindowSnowmanSchedule(300);Check(!squirrel.Due(299.99)&&squirrel.Due(300)&&!squirrel.Due(599.99)&&squirrel.Due(600),"squirrel five-minute interval");Check(squirrel.Due(1400)&&!squirrel.Due(1400.1)&&!squirrel.Due(1699.9)&&squirrel.Due(1700),"no catch-up bursts");var snowman=new WindowSnowmanSchedule();Check(!snowman.Due(599.99)&&snowman.Due(600)&&!snowman.Due(1199.99)&&snowman.Due(1200),"snowman ten minutes");
 var root=new SnowmanMotion(600,100,.6f,true,1);var child=new SnowmanMotion(650,100,.3f,true,1){Generation=1};int roots=0,children=0;for(int n=0;n<18000;n++){root.Tick(1.0/120,950,0,1400);child.Tick(1.0/120,950,0,1400);if(root.ChildPending){roots++;root.ChildPending=false;}if(child.ChildPending){children++;child.ChildPending=false;}}Check(roots==1&&children==0,"root builds one, descendant builds none");root.Grab();root.X=600;root.Y=100;root.Drop(new List<Ledge>());for(int n=0;n<9000;n++){root.Tick(1.0/120,950,0,1400);Check(!root.ChildPending,"capture does not reset completed parent");}
 Check(WindowTracker.IsDepartureEvent(0x16,0,0)&&WindowTracker.IsDepartureEvent(0x8001,0,0)&&WindowTracker.IsDepartureEvent(0x8003,0,0),"minimize destroy hide notification");Check(!WindowTracker.IsDepartureEvent(0x800B,0,0)&&!WindowTracker.IsDepartureEvent(0x8001,-4,0)&&!WindowTracker.IsDepartureEvent(0x8001,0,3),"movement and child events do not detach bank");Check(WindowSnowRelease.ShouldRelease(true,true,true,false,100)&&WindowSnowRelease.ShouldRelease(false,false,false,false,100)&&WindowSnowRelease.ShouldRelease(true,false,true,true,100),"minimize close event detach");Check(!WindowSnowRelease.ShouldRelease(true,false,true,false,100),"occluded/open window retained");
 using(var original=new SnowModel(901,1,3))using(var resized=new SnowModel(467,1,7)){original.Blizzard();double mass=original.Mass*original.Cell;SnowModel.Transfer(original,resized);Check(Math.Abs(resized.Mass*resized.Cell-mass)<.1,"resize preserves snow before close");var areas=WindowSnowRelease.SliceAreas(resized,9);double sum=0;foreach(double piece in areas){sum+=piece;var falling=new SnowFallMotion(300,200,piece,1);double previous=falling.Y;for(int n=0;n<300;n++){falling.Tick(1.0/120);Check(falling.Y>=previous,"released bank falls down");previous=falling.Y;}}Check(Math.Abs(sum-mass)<.1,"detached slices retain snow mass");}
 using(var a=new Atlas(1)){using(var worker=DrawnArt.Worker(0,a.WorkerScale))using(var pet=DrawnArt.Runner(0,a.PetScale)){int wh=OpaqueHeight(worker),ph=OpaqueHeight(pet);Check(Math.Abs(wh-ph)<=2,"equal visible penguin heights");}}
 Console.WriteLine("PASS: 5/10-minute schedules, no catch-up burst, one descendant, equal penguin height, minimize/close events, resize mass and falling bank physics.");}
 static int OpaqueHeight(Bitmap b){int top=b.Height,bottom=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>128){top=Math.Min(top,y);bottom=Math.Max(bottom,y);}return bottom-top+1;}
 static void StackOnWindow(){var window=new Ledge{Handle=new IntPtr(17),Bounds=new Rectangle(200,350,800,400)};var ledges=new List<Ledge>{window};var snow=new SnowmanMotion(500,350,.7f,true,1);snow.AdoptStackBase(500,350,1000,ledges);Check(snow.Support==window.Handle&&snow.Y==350,"stack stays on roof rather than teleporting to desktop");snow.Tick(1.0/120,1000,0,1600,ledges);Check(snow.Y==350&&snow.SupportOffset==300,"first animated frame preserves roof");window.Bounds.Offset(70,-40);snow.Tick(1.0/120,1000,0,1600,ledges);Check(snow.X==570&&snow.Y==310,"assembled snowman follows moved window");ledges.Clear();snow.Tick(1.0/120,1000,0,1600,ledges);Check(snow.State==SnowmanState.Falling&&snow.Y<1000,"closed support starts gravity, no teleport");var ground=new SnowmanMotion(500,1000,.7f,true,1);ground.AdoptStackBase(500,1000,1000,ledges);Check(ground.State==SnowmanState.Awakening&&ground.Support==IntPtr.Zero,"desktop assembly still works");var air=new SnowmanMotion(500,200,.7f,true,1);air.AdoptStackBase(500,200,1000,ledges);Check(air.State==SnowmanState.Falling&&air.Y==200,"unsupported stack starts at actual location");Console.WriteLine("PASS: manual stack inherits window support, follows movement, falls on closing, and retains desktop/air placement.");}
 static void Contact(){using(var m=new SnowModel(1000,1,42)){for(int i=0;i<m.Depth.Length;i++)m.Depth[i]=35;double before=m.Mass*m.Cell;double take=SnowContact.Collect(m,100,900,150,790,900,790,20);Check(take==0&&Math.Abs(m.Mass*m.Cell-before)<.001,"no airborne collection");take=SnowContact.Collect(m,100,900,150,860,900,860,20);Check(take>0&&Math.Abs(before-m.Mass*m.Cell-take)<.05,"contact transfers exact removed mass");before=m.Mass*m.Cell;take=SnowContact.Collect(m,100,900,-200,880,-50,880,20);Check(take==0&&Math.Abs(m.Mass*m.Cell-before)<.001,"outside surface no collection");for(int k=0;k<1000;k++){double x=100+k%500,y=k%2==0?700:880;double old=m.Mass*m.Cell;take=SnowContact.Collect(m,100,900,x,y,x+5,y,15);Check(take>=0&&Math.Abs(old-m.Mass*m.Cell-take)<.05,"repeated exact mass");if(y==700)Check(take==0,"repeated lifting stops collection");}}Console.WriteLine("PASS: actual snow contact, airborne/outside rejection, 1000 roll/lift cycles and mass conservation.");}
 static void Drain(Func<bool> done){var watch=System.Diagnostics.Stopwatch.StartNew();while(!done()){FramePreparation.Pump(2);System.Threading.Thread.Sleep(1);if(watch.Elapsed.TotalSeconds>30)throw new Exception("preparation timeout");}}
 static void Cache(){int before=Sprite.Allocated-Sprite.Released;using(var bank=new FrameBank(256,i=>DrawnArt.Worker(i,.64f),i=>DrawnArt.Identity("shovel",i),48)){var timer=System.Diagnostics.Stopwatch.StartNew();bank.Warm();double request=timer.Elapsed.TotalMilliseconds;Drain(()=>bank.Ready);Check(bank.Count==27,"256 worker exposures share 27 authored drawings");Check(bank.Bytes<4000000,"worker native image budget");for(int pass=0;pass<20;pass++)for(int i=0;i<256;i++)Check(bank[i]!=null,"warm worker frame available");Console.WriteLine("PASS: asynchronous worker preparation; 256 exposures / "+bank.Count+" cached drawings; UI request "+request.ToString("F2")+" ms (Linux managed sprite adapter).");}
 using(var bank=new FrameBank(100,i=>Artwork.Canvas(80,80),i=>i.ToString(),5,128000)){for(int i=0;i<100;i++){int n=i;bank.Request(n);Drain(()=>bank.Has(n));Check(bank.Count<=5&&bank.Bytes<=128000,"bounded LRU across 100 frames");}Check(!bank.Has(0)&&bank.Has(99),"old frames evicted");}Check(Sprite.Allocated-Sprite.Released==before,"all cache buffers released");var cancelled=new FrameBank(20,i=>Artwork.Canvas(100,100),i=>i.ToString());cancelled.Warm();cancelled.Dispose();for(int n=0;n<50;n++){FramePreparation.Pump();System.Threading.Thread.Sleep(1);}Check(Sprite.Allocated-Sprite.Released==before,"disposed bank commits no buffers");Console.WriteLine("PASS: cache limits, eviction, disposal while loading and zero retained test sprite buffers.");}
 static void Soak(){var roofs=new List<Ledge>{new Ledge{Handle=new IntPtr(77),Bounds=new Rectangle(200,400,800,300)}};var p=new PetMotion(500,100,1){State=PetState.Falling};var s=new SnowmanMotion(500,100,1,false,1);for(int frame=0;frame<216000;frame++){if(frame%600==0){p.Grab(p.X,p.Y);p.Drag(500,100);p.Drop(roofs);s.Grab();s.X=550;s.Y=100;s.Drop(roofs);}if(frame%180==0)roofs[0].Bounds=new Rectangle(200+frame%80,400+frame%120,800,300);var current=frame%1200<900?roofs:new List<Ledge>();p.Tick(1.0/60,current,x=>950);s.Tick(1.0/60,950,0,1400,current);Check(!double.IsNaN(p.X)&&!double.IsNaN(s.Y),"finite positions during soak");Check(Controller.PetFrame(p)>=0&&Controller.PetFrame(p)<352,"pet pose stays in range");Check(s.Pose>=0&&s.Pose<480,"snowman pose stays in range");}Console.WriteLine("PASS: 60 simulated minutes, 360 capture/release cycles, moving/disappearing supports and valid animation states.");
 using(var atlas=new Atlas(1)){atlas.PrepareWorker();atlas.PreparePets();Drain(()=>atlas.WorkerReady&&atlas.PetImages.Ready&&atlas.Runners.Ready);for(int i=0;i<352;i++){int frame=i;Drain(()=>atlas.PetSprite(frame,-1)!=null);Check(atlas.PetSprite(frame,-1)!=null,"all mirrored pet states available");}for(int i=0;i<256;i++)Check(atlas.Worker(i,0,1)!=null&&atlas.Worker(i,0,-1)!=null,"both worker directions ready");}Console.WriteLine("PASS: full atlas background loading, both worker directions and all 352 mirrored pet states.");}
 static void Preview(){using(var b=Artwork.Canvas(1600,1160))using(var g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(35,48,64));for(int i=0;i<8;i++){using(var p=DrawnArt.Worker(i*32,.75f))g.DrawImageUnscaled(p,i*195,10);using(var s=DrawnArt.Snowman(464+i*2,1))g.DrawImageUnscaled(s,i%4*390,210+i/4*210);using(var p=DrawnArt.Pet(i<4?64+i*8:96+(i-4)*8,1))g.DrawImageUnscaled(p,i%4*390,660+i/4*210);}b.Save("work/checks23/characters.png");}for(int i=0;i<5;i++)using(var image=SnowImpact.Render(45,i*.22,1,-1,0))image.Save("work/checks23/impact-"+i+".png");}
